import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十七卦 困 泽水困 兑上坎下","description":"周易 - 第四十七卦 困 泽水困 兑上坎下","frontmatter":{"title":"第四十七卦 困 泽水困 兑上坎下","description":"周易 - 第四十七卦 困 泽水困 兑上坎下"},"headers":[],"relativePath":"zh/classics/zhouyi/048.md","filePath":"zh/classics/zhouyi/048.md"}'),l={name:"zh/classics/zhouyi/048.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="困" tabindex="-1">困 <a class="header-anchor" href="#困" aria-label="Permalink to “困”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，贞，大人吉，无咎，有言不信。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>困，刚掩也。险以说，困而不失其所，亨；其唯君子乎？贞大人吉，以刚中也。有言不信，尚口乃穷也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>泽无水，困；君子以致命遂志。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>臀困于株木，入于幽谷，三岁不见。象 曰：入于幽谷，幽不明也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>困于酒食，朱绂方来，利用亨祀，征凶，无咎。象曰：困于酒食，中有庆也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>困于石，据于蒺藜，入于其宫，不见其妻，凶。象曰：据于蒺藜，乘刚也。入于其宫，不见其妻，不祥也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>来徐徐，困于金车，吝，有终。象曰：来徐徐，志在下也。虽不当位，有与也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>劓刖，困于赤绂，乃徐有说，利用祭祀。象曰：劓刖，志未得也。乃徐有说，以中直也。利用祭祀，受福也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>困于葛藟，于臲卼，曰动悔。有悔，征吉。象曰：困于葛藟，未当也。动悔，有悔吉，行也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
